use frame::weights_prelude::*;

/// Weight functions needed for `pallet_transaction_payment`.
pub trait WeightInfo {
	fn charge_transaction_payment() -> Weight;
}

/// Weights for `pallet_transaction_payment` using the Substrate node and recommended hardware.
pub struct SubstrateWeight<T>(PhantomData<T>);
impl<T: frame_system::Config> WeightInfo for SubstrateWeight<T> {
	// PLACEHOLDER: regenerated by /cmd bench on the PR
	// Conservative estimate for the check, `prepare_gas` and `burn_gas` of a `NonFungibleGasTank`
	// scanning `DefaultMaxScan` (4) items twice (the check and `prepare_gas`), then burning from the
	// noted tank, with no scan; rounded up. The fee extension's weight is added separately, by
	// `ChargeTransactionPayment::weight`.
	/// Storage: `Memberships::Account` (r:8 w:0)
	/// Proof: `Memberships::Account` (`max_values`: None, `max_size`: Some(90), added: 2565, mode: `MaxEncodedLen`)
	/// Storage: `Memberships::Attribute` (r:10 w:1)
	/// Proof: `Memberships::Attribute` (`max_values`: None, `max_size`: Some(481), added: 2956, mode: `MaxEncodedLen`)
	/// Storage: `Memberships::Collection` (r:1 w:1)
	/// Proof: `Memberships::Collection` (`max_values`: None, `max_size`: Some(82), added: 2557, mode: `MaxEncodedLen`)
	/// Storage: `NonFungibleGasTank::PayingItem` (r:1 w:2)
	/// Proof: `NonFungibleGasTank::PayingItem` (`max_values`: None, `max_size`: None, mode: `Measured`)
	fn charge_transaction_payment() -> Weight {
		Weight::from_parts(250_000_000, 30_000)
			.saturating_add(T::DbWeight::get().reads(32_u64))
			.saturating_add(T::DbWeight::get().writes(6_u64))
	}
}

